        if inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")

    # Show extra characters
    if len(inp) < len(outp):
        print(f"  Extra chars at end: '{outp[len(inp):]}'")
